import hashlib


class RecordProgram:
    """Recomputes the record's checkable result."""

    def __init__(self):
        self.figures = {"forgetting_tests": 12, "lifetimes_defined": 3, "memory_types": 3, "user_controls": 4}

    def run(self):
        total = sum(self.figures.values())
        return {"total": total,
                "digest": hashlib.sha256(str(total).encode()).hexdigest()}
